17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.ArrayList;
21	import java.util.Collection;
22	import java.util.List;
23	import java.util.Optional;
24	
25	import org.springframework.http.HttpHeaders;
26	import org.springframework.http.HttpStatus;
27	import org.springframework.http.ResponseEntity;
28	import org.springframework.samples.petclinic.mapper.OwnerMapper;
29	import org.springframework.samples.petclinic.mapper.PetMapper;
30	import org.springframework.samples.petclinic.mapper.VisitMapper;
31	import org.springframework.samples.petclinic.model.Owner;
32	import org.springframework.samples.petclinic.model.Pet;
33	import org.springframework.samples.petclinic.model.Visit;
34	import org.springframework.samples.petclinic.rest.advice.DuplicateHouseholdException;
35	import org.springframework.samples.petclinic.rest.advice.DuplicateTelephoneException;
36	import org.springframework.samples.petclinic.rest.advice.InvalidFieldsException;
37	import org.springframework.samples.petclinic.rest.advice.RequiredFieldsMissingException;
38	import org.springframework.samples.petclinic.rest.api.OwnersApi;
39	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
40	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
41	import org.springframework.samples.petclinic.rest.dto.PetDto;
42	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
43	import org.springframework.samples.petclinic.rest.dto.VisitDto;
44	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
45	import org.springframework.samples.petclinic.service.ClinicService;
46	import org.springframework.security.access.prepost.PreAuthorize;
47	import org.springframework.web.bind.annotation.CrossOrigin;
48	import org.springframework.web.bind.annotation.RequestMapping;
49	import org.springframework.web.bind.annotation.RestController;
50	import org.springframework.web.util.UriComponentsBuilder;
51	
52	import jakarta.transaction.Transactional;
53	
54	/**
55	 * @author Vitaliy Fedoriv
56	 */
57	
58	@RestController
59	@CrossOrigin(exposedHeaders = "errors, content-type")
60	@RequestMapping("/api")
61	public class OwnerRestControllerV1 implements OwnersApi {
62	
63	    private final ClinicService clinicService;
64	
65	    private final OwnerMapper ownerMapper;
66	
67	    private final PetMapper petMapper;
68	
69	    private final VisitMapper visitMapper;
70	
71	    public OwnerRestControllerV1(ClinicService clinicService,
72	                                 OwnerMapper ownerMapper,
73	                                 PetMapper petMapper,
74	                                 VisitMapper visitMapper) {
75	        this.clinicService = clinicService;
76	        this.ownerMapper = ownerMapper;
77	        this.petMapper = petMapper;
78	        this.visitMapper = visitMapper;
79	    }
80	
81	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
82	    @Override
83	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
84	        Collection<Owner> owners;
85	        if (lastName != null) {
86	            owners = this.clinicService.findOwnerByLastName(lastName);
87	        } else {
88	            owners = this.clinicService.findAllOwners();
89	        }
90	        if (owners.isEmpty()) {
91	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
92	        }
93	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
94	    }
95	
96	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
97	    @Override
98	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
99	        Owner owner = this.clinicService.findOwnerById(ownerId);
100	        if (owner == null) {
101	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
102	        }
103	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
104	    }
105	
106	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
107	    @Override
108	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
109	        prepareNewOwner(ownerFieldsDto);
110	        HttpHeaders headers = new HttpHeaders();
111	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
112	        if (owner.getRegistrationDate() == null) {
113	            owner.setRegistrationDate(LocalDate.now());
114	        }
115	        owner.setCustomerCode(nextCustomerCode(owner.getLastName()));
116	        assignHousehold(owner, ownerFieldsDto);
117	        this.clinicService.saveOwner(owner);
118	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
119	        headers.setLocation(UriComponentsBuilder.newInstance()
120	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
121	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
122	    }
123	
124	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
125	    @Override
126	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
127	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
128	        if (currentOwner == null) {
129	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
130	        }
131	        currentOwner.setAddress(ownerFieldsDto.getAddress());
132	        currentOwner.setCity(ownerFieldsDto.getCity());
133	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
134	        currentOwner.setLastName(ownerFieldsDto.getLastName());
135	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
136	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
137	        this.clinicService.saveOwner(currentOwner);
138	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
139	    }
140	
141	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
142	    @Transactional
143	    @Override
144	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
145	        Owner owner = this.clinicService.findOwnerById(ownerId);
146	        if (owner == null) {
147	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
148	        }
149	        this.clinicService.deleteOwner(owner);
150	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
151	    }
152	
153	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
154	    @Override
155	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
156	        Owner owner = this.clinicService.findOwnerById(ownerId);
157	        if (owner == null) {
158	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
159	        }
160	        HttpHeaders headers = new HttpHeaders();
161	        Pet pet = petMapper.toPet(petFieldsDto);
162	        owner.setId(ownerId);
163	        pet.setOwner(owner);
164	        pet.getType().setName(null);
165	        this.clinicService.savePet(pet);
166	        PetDto petDto = petMapper.toPetDto(pet);
167	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
168	            .buildAndExpand(pet.getId()).toUri());
169	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
170	    }
171	
172	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
173	    @Override
174	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
175	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
176	        if (currentOwner != null) {
177	            Pet currentPet = this.clinicService.findPetById(petId);
178	            if (currentPet != null) {
179	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
180	                currentPet.setName(petFieldsDto.getName());
181	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
182	                this.clinicService.savePet(currentPet);
183	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
184	            }
185	        }
186	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
187	    }
188	
189	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
190	    @Override
191	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
192	        HttpHeaders headers = new HttpHeaders();
193	        Visit visit = visitMapper.toVisit(visitFieldsDto);
194	        Pet pet = new Pet();
195	        pet.setId(petId);
196	        visit.setPet(pet);
197	        this.clinicService.saveVisit(visit);
198	        VisitDto visitDto = visitMapper.toVisitDto(visit);
199	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
200	            .buildAndExpand(visit.getId()).toUri());
201	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
202	    }
203	
204	
205	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
206	    @Override
207	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
208	        Owner owner = this.clinicService.findOwnerById(ownerId);
209	        if (owner != null) {
210	            Pet pet = owner.getPet(petId);
211	            if (pet != null) {
212	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
213	            }
214	        }
215	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
216	    }
217	
218	    /**
219	     * Applies the intake rules a newly submitted owner must satisfy before it is persisted.
220	     * The required fields are checked, the telephone and email are normalized in place, and
221	     * the resulting telephone is rejected when it already belongs to another owner. Each rule
222	     * signals a violation by throwing, which the exception advice renders as the matching 4xx
223	     * response; when the method returns normally {@code ownerFieldsDto} is normalized and ready
224	     * to be mapped and saved.
225	     *
226	     * @param ownerFieldsDto the submitted owner fields, normalized in place
227	     */
228	    private void prepareNewOwner(OwnerFieldsDto ownerFieldsDto) {
229	        validateRequiredFields(ownerFieldsDto);
230	        ownerFieldsDto.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
231	        ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
232	        rejectDuplicateTelephone(ownerFieldsDto.getTelephone());
233	        rejectDuplicateHousehold(ownerFieldsDto);
234	    }
235	
236	    /**
237	     * Builds the customer code assigned to a newly created owner. The code is formatted as
238	     * {@code '<LAST3>-<NNNN>'}, where {@code LAST3} is the upper-cased first three letters of
239	     * the owner's last name and {@code NNNN} is a global 4-digit zero-padded sequence equal to
240	     * one more than the current number of owners. For example the seventh owner named
241	     * {@code 'Smith'} is assigned {@code 'SMI-0007'}.
242	     *
243	     * @param lastName the owner's last name
244	     * @return the formatted customer code
245	     */
246	    private String nextCustomerCode(String lastName) {
247	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
248	        long sequence = this.clinicService.findAllOwners().size() + 1L;
249	        return String.format("%s-%04d", last3, sequence);
250	    }
251	
252	    /**
253	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city}
254	     * or {@code telephone} is missing or blank. A field that is only whitespace is treated as
255	     * blank. When any field fails, a {@link RequiredFieldsMissingException} is thrown carrying
256	     * the names of every offending field, which the exception advice renders as a 400 response
257	     * with an {@code errors} array.
258	     *
259	     * @param ownerFieldsDto the submitted owner fields
260	     */
261	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
262	        List<String> missing = new ArrayList<>();
263	        addIfBlank(missing, "firstName", ownerFieldsDto.getFirstName());
264	        addIfBlank(missing, "lastName", ownerFieldsDto.getLastName());
265	        addIfBlank(missing, "address", ownerFieldsDto.getAddress());
266	        addIfBlank(missing, "city", ownerFieldsDto.getCity());
267	        addIfBlank(missing, "telephone", ownerFieldsDto.getTelephone());
268	        if (!missing.isEmpty()) {
269	            throw new RequiredFieldsMissingException(missing);
270	        }
271	    }
272	
273	    private void addIfBlank(List<String> missing, String fieldName, String value) {
274	        if (value == null || value.isBlank()) {
275	            missing.add(fieldName);
276	        }
277	    }
278	
279	    /**
280	     * Normalizes a submitted telephone number into E.164 form. Spaces, dashes and brackets
281	     * are stripped. When a leading {@code '+'} and country code are present they are kept as
282	     * given; otherwise the country code {@code '+61'} is assumed and a single leading
283	     * {@code '0'} is dropped from the national digits. The result must be a {@code '+'}
284	     * followed by 8 to 15 digits. The normalized E.164 value is what gets stored and returned.
285	     * When the value cannot form a valid E.164 number an {@link InvalidFieldsException} is
286	     * thrown, which the exception advice renders as a 400 response naming the {@code telephone}
287	     * field. For example {@code "0412 345 678"} becomes {@code "+61412345678"}.
288	     *
289	     * @param telephone the submitted telephone value
290	     * @return the normalized E.164 telephone
291	     */
292	    private String normalizeTelephone(String telephone) {
293	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
294	        String e164;
295	        if (cleaned.startsWith("+")) {
296	            e164 = "+" + cleaned.substring(1);
297	        } else {
298	            String national = cleaned;
299	            if (national.startsWith("0")) {
300	                national = national.substring(1);
301	            }
302	            e164 = "+61" + national;
303	        }
304	        if (!e164.matches("^\\+[0-9]{8,15}$")) {
305	            throw new InvalidFieldsException(List.of("telephone"));
306	        }
307	        return e164;
308	    }
309	
310	    /**
311	     * Pattern for a syntactically valid email address: a non-empty local part, an {@code @},
312	     * and a domain containing at least one dot, none of the parts holding whitespace or a
313	     * second {@code @}.
314	     */
315	    private static final java.util.regex.Pattern EMAIL_PATTERN =
316	        java.util.regex.Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
317	
318	    /**
319	     * Normalizes an optional owner email. An email is optional, so a {@code null} value is
320	     * accepted and returned unchanged. When present it must be a syntactically valid address;
321	     * the value is stored and returned lower-cased. When present but invalid an
322	     * {@link InvalidFieldsException} is thrown, which the exception advice renders as a 400
323	     * response naming the {@code email} field.
324	     *
325	     * @param email the submitted email value, or {@code null} when omitted
326	     * @return the lower-cased email, or {@code null} when none was supplied
327	     */
328	    private String normalizeEmail(String email) {
329	        if (email == null) {
330	            return null;
331	        }
332	        String trimmed = email.trim();
333	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
334	            throw new InvalidFieldsException(List.of("email"));
335	        }
336	        return trimmed.toLowerCase(java.util.Locale.ROOT);
337	    }
338	
339	    /**
340	     * Rejects a new owner whose normalized telephone is already used by any existing owner.
341	     * The telephone is stored in its normalized E.164 form, so a plain equality check
342	     * against every owner's telephone compares E.164 values. When a match is found a
343	     * {@link DuplicateTelephoneException} is thrown, which the exception advice renders as a
344	     * 409 Conflict response.
345	     *
346	     * @param telephone the normalized telephone of the owner being created
347	     */
348	    private void rejectDuplicateTelephone(String telephone) {
349	        boolean taken = this.clinicService.findAllOwners().stream()
350	            .anyMatch(existing -> telephone.equals(existing.getTelephone()));
351	        if (taken) {
352	            throw new DuplicateTelephoneException(telephone);
353	        }
354	    }
355	
356	    /**
357	     * Rejects a new owner whose {@code lastName} and {@code address} already belong to another
358	     * owner, i.e. one that shares its household (see {@link #findHouseholdMate(String, String)}
359	     * for how that identity is compared). A request may bypass this rule by setting
360	     * {@code sharesHousehold} to {@code true}, allowing several owners to share one household.
361	     * When a household mate is found and the request did not opt in a
362	     * {@link DuplicateHouseholdException} is thrown, which the exception advice renders as a 409
363	     * Conflict response.
364	     *
365	     * @param ownerFieldsDto the submitted owner fields
366	     */
367	    private void rejectDuplicateHousehold(OwnerFieldsDto ownerFieldsDto) {
368	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
369	            return;
370	        }
371	        boolean taken = findHouseholdMate(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress()).isPresent();
372	        if (taken) {
373	            throw new DuplicateHouseholdException(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
374	        }
375	    }
376	
377	    /**
378	     * Assigns the shared {@code householdId} for an owner created with {@code sharesHousehold}
379	     * set to {@code true}. The identifier is derived deterministically from the owner's
380	     * household identity (its {@code lastName} and {@code address}, see
381	     * {@link #householdIdFor(String, String)}), so every owner in the same household resolves to
382	     * the same stable value. The new owner receives that value, and any existing household mates
383	     * that do not yet carry it are updated so the whole household shares one identifier. When the
384	     * request did not opt in the owner is left without a household identifier.
385	     *
386	     * @param owner the newly created owner, mutated in place with its household identifier
387	     * @param ownerFieldsDto the submitted owner fields carrying the {@code sharesHousehold} flag
388	     */
389	    private void assignHousehold(Owner owner, OwnerFieldsDto ownerFieldsDto) {
390	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
391	            return;
392	        }
393	        String householdId = householdIdFor(owner.getLastName(), owner.getAddress());
394	        owner.setHouseholdId(householdId);
395	        for (Owner mate : findHouseholdMates(owner.getLastName(), owner.getAddress())) {
396	            if (!householdId.equals(mate.getHouseholdId())) {
397	                mate.setHouseholdId(householdId);
398	                this.clinicService.saveOwner(mate);
399	            }
400	        }
401	    }
402	
403	    /**
404	     * Derives the stable {@code householdId} shared by every owner in the household identified by
405	     * the given {@code lastName} and {@code address}. The two fields are normalized exactly as
406	     * household identity is compared elsewhere (case-insensitively, with collapsed whitespace) and
407	     * hashed with SHA-256, so any two owners in the same household — regardless of creation order —
408	     * resolve to the same identifier. The result is formatted as {@code 'HH-<16 hex chars>'}.
409	     *
410	     * @param lastName the household's last name
411	     * @param address the household's address
412	     * @return the deterministic household identifier
413	     */
414	    private String householdIdFor(String lastName, String address) {
415	        String key = collapseWhitespace(lastName).toLowerCase(java.util.Locale.ROOT) + "|"
416	            + collapseWhitespace(address).toLowerCase(java.util.Locale.ROOT);
417	        try {
